import{_ as a,c as s,a as n,o as i}from"./app-DWIxxE3W.js";const l={};function d(r,e){return i(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="المتغيرات-صناديقك-الرقمية" tabindex="-1"><a class="header-anchor" href="#المتغيرات-صناديقك-الرقمية"><span>المتغيرات: صناديقك الرقمية</span></a></h1><h2 id="ما-هو-المتغير؟" tabindex="-1"><a class="header-anchor" href="#ما-هو-المتغير؟"><span>ما هو المتغير؟</span></a></h2><p>تخيل أنك تحزم أمتعتك للانتقال إلى منزل جديد. تضع كتبك في صندوق وتكتب كلمة &quot;كتب&quot; في الخارج. لاحقًا، عندما تحتاج إلى كتاب، لن تبحث في كل مكان — بل ستعثر ببساطة على الصندوق المكتوب عليه &quot;كتب&quot;.</p><p>في البرمجة، <strong>المتغير (Variable)</strong> هو بالضبط هذا: صندوق يحمل ملصقاً حيث نقوم بتخزين المعلومات (البيانات) داخل ذاكرة الكمبيوتر. نعطي الصندوق اسمًا حتى نتمكن بسهولة من العثور على تلك المعلومات واستخدامها لاحقًا!</p><p>تتيح لنا المتغيرات تخزين أشياء مثل اسم المستخدم، أو أعلى نتيجة في لعبة، أو كلمة مرور سرية.</p><h2 id="إنشاء-واستخدام-متغير" tabindex="-1"><a class="header-anchor" href="#إنشاء-واستخدام-متغير"><span>إنشاء واستخدام متغير</span></a></h2><p>لإنشاء صندوق جديد (متغير) ووضع شيء بداخله، نستخدم الكلمة <code>SET</code> في الكود الزائف.</p><div class="language-pseudo line-numbers-mode" data-highlighter="prismjs" data-ext="pseudo"><pre><code><span class="line">SET my_name TO &quot;Arya&quot;</span>
<span class="line">PRINT my_name</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p><em>(هذا سيطبع: Arya)</em></p><p>دعنا نوضح ما حدث للتو:</p><ol><li><code>SET</code> تخبر الكمبيوتر أننا نقوم بإنشاء أو تحديث متغير.</li><li><code>my_name</code> هو الملصق الذي كتبناه على صندوقنا.</li><li><code>TO</code> تخبر الكمبيوتر بوضع البيانات في الصندوق.</li><li><code>&quot;Arya&quot;</code> هي البيانات (سلسلة نصية) التي قمنا بتخزينها بالداخل.</li></ol><p>أفضل جزء في المتغيرات هو أنها يمكن أن &quot;تتغير&quot;! يمكنك تغيير ما بداخل الصندوق لاحقًا:</p><div class="language-pseudo line-numbers-mode" data-highlighter="prismjs" data-ext="pseudo"><pre><code><span class="line">SET favorite_food TO &quot;بيتزا&quot;</span>
<span class="line">PRINT favorite_food </span>
<span class="line">// يطبع: بيتزا</span>
<span class="line"></span>
<span class="line">// لاحقاً، نغير رأينا!</span>
<span class="line">SET favorite_food TO &quot;تاكو&quot;</span>
<span class="line">PRINT favorite_food </span>
<span class="line">// يطبع: تاكو</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="الثوابت-constants" tabindex="-1"><a class="header-anchor" href="#الثوابت-constants"><span>الثوابت (Constants)</span></a></h2><p>أحيانًا، ترغب في تخزين معلومات لا ينبغي أن تتغير <strong>أبدًا</strong>. على سبيل المثال، تاريخ ميلادك أو قيمة باي (Pi).</p><p>بالنسبة للأشياء التي يجب أن تظل ثابتة، يمكننا تحديد أن الصندوق مقفل باستخدام <code>CONSTANT</code>.</p><div class="language-pseudo line-numbers-mode" data-highlighter="prismjs" data-ext="pseudo"><pre><code><span class="line">CONSTANT birth_year TO 1995</span>
<span class="line">PRINT birth_year</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>إذا حاولت تغيير <code>CONSTANT</code>، ستفشل الخوارزمية لأن البيانات محمية.</p><h2 id="المتغيرات-والرياضيات" tabindex="-1"><a class="header-anchor" href="#المتغيرات-والرياضيات"><span>المتغيرات والرياضيات</span></a></h2><p>بما أن المتغيرات هي مجرد صناديق تحتوي على بيانات، فإذا كانت تحتوي على أرقام، يمكننا إجراء العمليات الحسابية معها!</p><div class="language-pseudo line-numbers-mode" data-highlighter="prismjs" data-ext="pseudo"><pre><code><span class="line">SET score TO 10</span>
<span class="line">SET score TO score + 5 </span>
<span class="line"></span>
<span class="line">PRINT score </span>
<span class="line">// يطبع: 15</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>نحن نخبر الكمبيوتر: &quot;خذ أيًا كان الموجود حاليًا داخل صندوق <code>score</code> (وهو 10)، أضف إليه 5، وضع النتيجة الجديدة (15) مرة أخرى في صندوق <code>score</code>!&quot;</p><h2 id="مراجعة-المتغيرات" tabindex="-1"><a class="header-anchor" href="#مراجعة-المتغيرات"><span>مراجعة المتغيرات</span></a></h2><p>دعنا نراجع ما تعلمناه:</p><ul><li><strong>المتغيرات (Variables)</strong> هي صناديق بأسماء تُستخدم لتخزين البيانات.</li><li>استخدم <code>SET ... TO ...</code> لوضع البيانات داخل المتغير.</li><li>يمكن تحديث المتغيرات أو تغييرها في أي وقت في الخوارزمية الخاصة بك.</li><li>استخدم <code>CONSTANT ... TO ...</code> إذا كان يجب قفل البيانات وعدم تغييرها أبدًا.</li><li>يمكنك القيام بالعمليات الحسابية مع المتغيرات إذا كانت تحتوي على أرقام.</li></ul>`,25)])])}const o=a(l,[["render",d]]),t=JSON.parse('{"path":"/ar/variables.html","title":"المتغيرات: صناديقك الرقمية","lang":"ar-MA","frontmatter":{},"headers":[{"level":2,"title":"ما هو المتغير؟","slug":"ما-هو-المتغير؟","link":"#ما-هو-المتغير؟","children":[]},{"level":2,"title":"إنشاء واستخدام متغير","slug":"إنشاء-واستخدام-متغير","link":"#إنشاء-واستخدام-متغير","children":[]},{"level":2,"title":"الثوابت (Constants)","slug":"الثوابت-constants","link":"#الثوابت-constants","children":[]},{"level":2,"title":"المتغيرات والرياضيات","slug":"المتغيرات-والرياضيات","link":"#المتغيرات-والرياضيات","children":[]},{"level":2,"title":"مراجعة المتغيرات","slug":"مراجعة-المتغيرات","link":"#مراجعة-المتغيرات","children":[]}],"git":{"updatedTime":1778106929000,"contributors":[{"name":"Aymane Benhima","username":"","email":"aymanebenhima.gmail.com","commits":2}],"changelog":[{"hash":"02c5b3cc51f9da680f9ea7a50ccdf218e1fb7b68","time":1778106929000,"email":"aymanebenhima.gmail.com","author":"Aymane Benhima","message":"feat: add multilingual documentation for variables, conditionals, and loops"},{"hash":"d0ac587de5ea00d050dbb9b4ba983301d2e58cae","time":1778105142000,"email":"aymanebenhima.gmail.com","author":"Aymane Benhima","message":"feat: initialize project with VuePress and multilingual documentation for JS fundamentals"}]},"filePathRelative":"ar/variables.md"}');export{o as comp,t as data};
